C>MODULE AAMBSREL    *DECK AABMS
C> @brief   Contains exponents and coefficients for the 
C>          relativistic AAMBS
C>
C> @author  George Schoendorff
C>
C> @date    July 13, 2022
C>
C> @details Each parameter is named as follows:
C>          First part:  E = exponent array
C>                       C = coefficient array
C>          Second part = Atomic symbol
C>          Third part  = Angular momentum if exponents or
C>                              orbital if coefficients
C>          Fourth part = R if relativistic
C>
C>          Example: The relativistic carbon 2s orbital will use
C>                   ECSR for the exponent array and CC2SR for the
C>                   coefficient array. Both arrays will have a
C>                   length of NECSR (from aambs_limits in
C>                   mod_vvos.src).
C>
C>          Note that the "relativistic" AAMBS for H and He is
C>          really just the nonrelativistic version repackaged
C>          as a relativistic AAMBS.
C>
      module aambsrel
      use prec, only: dp
      use aambs_limits
      implicit none
      public

      REAL(KIND=DP) :: EHSR(NEHS)
      REAL(KIND=DP) :: CH1SR(NEHS)
