C
C        ----- GET AN EVEN-TEMPERED BASIS SET (FOR H-AR) -----
C     M.W.SCHMIDT, K.RUEDENBERG  J.CHEM.PHYS. 71, 3951-3962(1979)
C        ----- GET A WELL-TEMPERED BASIS SET (BEYOND AR) -----
C     S.HUZINAGA, M.KLOBUKOWSKI  CHEM.PHYS.LETT. 212, 260-264(1993)
C
C     THIS ROUTINE RETURNS EXPONENTS AND CONTRACTION COEFFICIENTS:
C
C     GTO EXPONENTS ARE THE OPTIMAL ALPHA,BETA VALUES FOR H-NE,
C     AND ARE FROM REGULARIZED ALPHA,BETA FOR NA-AR.  SIZES ARE
C     H-HE:8S  LI-BE:14S  B-NE:14S,7P  NA-MG:18S,9P  AL-AR:18S,12P
C     THESE ARE CHOSEN TO BE ABOUT ONE MILLIHARTREE OR SO AWAY FROM
C     THE EXACT ATOMIC SCF LIMITS (REPORTED IN THAT PAPER ALSO).
C
C     GENERAL CONTRACTION TO ATOMIC MINIMAL BASIS SET (DZ=.FALSE.),
C     OR FLOATING THE MOST DIFFUSE GTO IN EACH SYMMETRY (DZ=.TRUE.)
C
C     SPHERICAL DENSITY ATOMIC CALCULATIONS WILL GIVE ENERGIES
C         H -  FINAL ROHF ENERGY IS      -0.4999742933
C        HE -  FINAL RHF ENERGY IS       -2.8615070990
C        LI -  FINAL ROHF ENERGY IS      -7.4326894443
C        BE -  FINAL RHF ENERGY IS      -14.5729514471
C         B -  FINAL GVB ENERGY IS      -24.5289020592
C         C -  FINAL GVB ENERGY IS      -37.6883034560
C         N -  FINAL ROHF ENERGY IS     -54.4003685090
C         O -  FINAL GVB ENERGY IS      -74.8084211734
C         F -  FINAL GVB ENERGY IS      -99.4077883999
C        NE -  FINAL RHF ENERGY IS     -128.5447548872
C        NA -  FINAL ROHF ENERGY IS    -161.8583450857
C        MG -  FINAL RHF ENERGY IS     -199.6139973762
C        AL -  FINAL GVB ENERGY IS     -241.8758111063
C        SI -  FINAL GVB ENERGY IS     -288.8536108276
C         P -  FINAL ROHF ENERGY IS    -340.7179325784
C         S -  FINAL GVB ENERGY IS     -397.5038627824
C        CL -  FINAL GVB ENERGY IS     -459.4808442239
C        AR -  FINAL RHF ENERGY IS     -526.8160832671
C
C         INFORMATION FOR WELL-TEMPERED BASIS SETS IS
C            SIGERU HUZINAGA, MARIUSZ KLOBUKOWSKI
C         CHEMICAL PHYSICS LETTERS 212, 260-264(1993)
C         S.HUZINAGA, B.MIGUEL  CHEM.PHYS.LETT. 175, 289-291(1990)
C  Parameters not published obtained by e-mail from Mariusz Klobukowski
C
C     SPHERICAL DENSITY ATOMIC CALCULATIONS WILL GIVE ENERGIES
C         K -  FINAL ROHF ENERGY IS        -599.1647582216
C        Ca -  FINAL RHF ENERGY IS         -676.7581539521
C        -------------------------------------------------
C        See below for 1st row TM information
C        -------------------------------------------------
C        Ga -  FINAL ORMAS ENERGY IS      -1923.2609473568
C        Ge -  FINAL ORMAS ENERGY IS      -2075.3596812168
C        As -  FINAL ORMAS ENERGY IS      -2234.2386067054
C        Se -  FINAL ORMAS ENERGY IS      -2399.8675616830
C        Br -  FINAL ORMAS ENERGY IS      -2572.4412824834
C        Kr -  FINAL RHF   ENERGY IS      -2752.0549265471
C        Rb -  FINAL ROHF  ENERGY IS      -2938.3573572882
C        Sr -  FINAL RHF   ENERGY IS      -3131.5455885752
C        -------------------------------------------------
C        See below for 2nd row TM information
C        -------------------------------------------------
C        In -  FINAL ORMAS ENERGY IS      -5740.1690181907
C        Sn -  FINAL ORMAS ENERGY IS      -6022.9315716520
C        Sb -  FINAL ORMAS ENERGY IS      -6313.4852054922
C        Te -  FINAL ORMAS ENERGY IS      -6611.7839478472
C         I -  FINAL ORMAS ENERGY IS      -6917.9807871755
C        Xe -  FINAL RHF   ENERGY IS      -7232.1382564645
C
C
CGS
C      The above documentation is from the original implementation of
C      the non-relativistic AAMBS. It is still valid. However, the
C      original implementation generated the exponents on the fly.
C      Currently, the exponents are stored as data arrays. In some
C      cases this difference in implementation leads to rounding 
C      errors that result in normalization of almost, but no quite,
C      1.0. In these cases, the coefficients are recomputed while
C      the original coefficients are retained in commented arrays.
CGS
C
C Hydrogen
C
      DATA EHS /
     *  8.65403515E-02, 2.46095663E-01, 6.99824697E-01, 1.99009849E+00,
     *  5.65926298E+00, 1.60933027E+01, 4.57646859E+01, 1.30141495E+02/
